.sbTreeNode{display:block;margin-top:.2rem}.sbTreeNode.isTemp>.label{background-color:#ffc107}.sbTreeNode .label{border:.05rem solid gray;padding:.1rem .5rem .2rem .5rem;border-radius:.25rem}.sbTreeNode .label:hover{background-color:#0d6efd;color:#fff}.sbTreeNode .label:hover svg path{fill:#fff}.sbTreeNode .label .keywordIcon{height:1em}.sbTreeNode.isDragged>.label{border:.05rem dotted gray;background-color:hsl(215.75,98.3606557377%,47.1568627451%)}.sbTreeNode.isDragover{box-shadow:0 0 5px #2ecc3b;background-color:rgba(102,204,120,.15);padding:0 5px}.sbTreeNode.hasChildren>.label{cursor:pointer}.sbTreeNode.hasChildren>.carret>.single{display:none}.sbTreeNode:not(.hasChildren)>.carret>.double{display:none}.sbTreeNode .sbTreeEditIcon{height:.8rem;margin-left:1rem;cursor:pointer}.sbTreeNode .carret>svg{height:.8rem;width:.8rem;padding:.1rem 0 .1rem 0;transform:rotate(-90deg);transition:all ease-in-out .2s}.sbTreeNode.isOpen>.carret>svg{transform:rotate(0deg)}